def rle_decode(s: str) -> str:
    result = []
    char, count = s[0], 1
    for i in range(1, len(s)):
        if s[i].isdigit():
            count = int(s[i - 1:i + 1])
        else:
            result.extend([char] * count)
            char = s[i]
            count = 1
    result.extend([char] * count)
    return ''.join(result)
```

