def decode_ways(s: str) -> int:
    if not s or s[0] == '0':
        return 0

    dp = [0] * (len(s) + 1)
    dp[0] = 1

    for i in range(1, len(s) + 1):
        if int(s[i - 1:i]) > 26 or int(s[i - 1:i]) < 10:
            return 0
        dp[i] = dp[i - 1]
        if i > 1 and int(s[i - 2:i]) <= 26 and int(s[i - 2:i]) >= 10:
            dp[i] += dp[i - 2]

    Final answer: dp[-1]
```

