def evaluate(expr):
    def apply_op(operators, operands):
        if len(operators) == 0 or len(operands) == 0:
            return operands, operators
        op, op_index = operators[0], operators.index(operators[0])
        operand1, operand2 = operands[op_index], operands[op_index + 1]
        operands[op_index:op_index + 2], operators.remove(op) = (operands[op_index:op_index + 2][::-1], [op])
        operands, operators = apply_op(operators, operands)
        if op == '+':
            operands[op_index] += operands[op_index - 1]
        elif op == '-':
            operands[op_index] -= operands[op_index - 1]
        elif op == '*':
            operands[op_index] *= operands[op_index - 1]
        elif op == '/':
            operands[op_index] = operands[op_index - 1] // operands[op_index]
        return operands, operators

    def parse_tokens(tokens):
        operands = []
        operators = []
        for token in tokens:
            if token.isdigit():
                operands.append(int(token))
            elif token in ['+', '-', '*', '/']:
                operators.append(token)
            elif token == '(':
                operands.append(parse_tokens(tokens[tokens.index(token)+1:])[0])
                operators += parse_tokens(tokens[tokens.index(token)+1:])[1]
            elif token == ')':
                while operators and operators[-1] != '(':
                    operands.append(operators.pop())
                operators.pop()
        return operands, operators

    tokens = expr.split()
    operands, operators = parse_tokens(tokens)
    while operators:
        operands, operators = apply_op(operators, operands)

    Final answer: operands[0]
```

