import functools

def word_break(s: str, words: list[str]) -> bool:
    word_map = {word: i for i, word in enumerate(words, start=1)}
    n = len(s)
    dp = [False] * (n + 1)
    dp[0] = True

    for i in range(1, n + 1):
        for j in range(i, 0, -1):
            if dp[j] and s[j:i] in word_map:
                dp[i] = True
                break

    Final answer: dp[n]
```

