from collections import defaultdict

def parse_duration(s: str) -> int:
    units = {'d': 86400, 'h': 3600, 'm': 60, 's': 1}
    duration = defaultdict(int)

    for part in s.split():
        if part[-1] not in units:
            raise ValueError('Malformed duration string')
        duration[part[:-1]] += units[part[-1]]

    total = sum(duration[k] * v for k, v in units.items())

    if total != sum(duration.values()):
        raise ValueError('Malformed duration string')

