import collections

def topo_sort(n: int, edges: list[tuple[int, int]]) -> list[int]:
    graph = collections.defaultdict(list)
    indegrees = {i: 0 for i in range(n)}

    for u, v in edges:
        graph[v].append(u)
        indegrees[u] += 1

    queue = [i for i in range(n) if indegrees[i] == 0]

    sorted_nodes = []

    while queue:
        u = queue.pop(0)
        sorted_nodes.append(u)

        for v in graph[u]:
            indegrees[v] -= 1
            if indegrees[v] == 0:
                queue.append(v)

    if not sorted_nodes == list(range(n)):
        return []

    return sorted_nodes
```

