def n_queens(n):
    if n < 1 or n > 10:
        raise ValueError("n must be between 1 and 10")

    columns = [-1] * n
    count = 0

    def is_safe(x, y):
        for i in range(x):
            if columns[i] == y or abs(columns[i] - y) == abs(i - x):
                return False
        return True

    def place_queens(x):
        if x == n:
            count += 1
        else:
            for y in range(n):
                if is_safe(x, y):
                    columns[x] = y
                    place_queens(x + 1)
                    columns[x] = -1

    place_queens(0)
    return count
