def regex_match(s, p):
    if not p:
        return not s

    i, j = 0, 0
    while i < len(s) and j < len(p):
        if p[j] == s[i] or p[j] == '.':
            i += 1
            j += 1
        elif p[j] == '*':
            if p[j - 1] == s[i] or p[j - 1] == '.':
                i += 1
                j += 1
            else:
                j -= 1
    return j == len(p)
```

